 for(const fault of [1,12,25])it(`rolls back all source and catalogs on late CREATE failure ${fault}`,async()=>{await eventHook(fault);await ordinary();await unchangedRefusal(migration,'fixture_late_creation_fault');expect((await db.query('SELECT * FROM fixture.ddl_log')).rows).toEqual([])})
